// WooCommerce registers its template hooks after snippets load, so move the form on "init".
add_action( 'init', 'perfectpixel_move_coupon_form' );
add_filter( 'woocommerce_coupons_enabled', 'perfectpixel_coupon_form_cart' );

function perfectpixel_move_coupon_form() {
	remove_action( 'woocommerce_before_checkout_form', 'woocommerce_checkout_coupon_form', 10 );
	add_action( 'woocommerce_after_checkout_form', 'woocommerce_checkout_coupon_form' );
}

function perfectpixel_coupon_form_cart( $enabled ) {
	if ( 'yes' === '{{coupon_hide_on_cart}}' && function_exists( 'is_cart' ) && is_cart() ) {
		return false;
	}
	return $enabled;
}
